import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int height = scanner.nextInt();
        int position = scanner.nextInt();
        scanner.close();

        int result = 0;
        int leftBound = 1;
        int rightBound = (int) Math.pow(2, height);
        int currentLevel = height;
        String direction = "L";

        while (currentLevel > 0) {
            double mid = (leftBound + rightBound) / 2.0;
            if (direction.equals("L")) {
                if (position > mid) {
                    result += totalRes(currentLevel) + 1;
                    leftBound = (int) mid + 1;
                } else if (position < mid) {
                    int sum = leftBound + rightBound;
                    int adjustment = (sum % 2 != 0) ? 1 : 0;
                    rightBound = (int) mid + adjustment - 1;
                    result += 1;
                    direction = "R";
                }
                currentLevel--;
            } else { // direction == "R"
                if (position < mid) {
                    int sum = leftBound + rightBound;
                    int adjustment = (sum % 2 != 0) ? 1 : 0;
                    rightBound = (int) mid + adjustment - 1;
                    result += totalRes(currentLevel) + 1;
                } else if (position > mid) {
                    result += 1;
                    leftBound = (int) mid + 1;
                    direction = "L";
                }
                currentLevel--;
            }
        }
        System.out.println(result);
    }

    private static int totalRes(int n) {
        int cache = 1;
        int total = 0;
        for (int i = 0; i < n; i++) {
            total += cache;
            cache *= 2;
        }
        return total;
    }
}

